+.footer-card p{margin:0;color:var(--sub);line-height:1.7}
+.links{display:flex;flex-wrap:wrap;gap:10px}
+.links a{padding:8px 10px;border-radius:999px;border:1px solid var(--border);background:rgba(246,247,251,.7);font-weight:750;color:var(--text)}
+.links a:hover{text-decoration:none;transform:translateY(-1px)}
+.trending{display:flex;flex-wrap:wrap;gap:8px}
+.trending span{padding:8px 10px;border-radius:999px;border:1px dashed rgba(16,17,35,.18);color:rgba(16,17,35,.72);background:rgba(255,255,255,.7);font-weight:700}
